package com.example.helpdesk.service; import com.example.helpdesk.model.*; import com.example.helpdesk.repo.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class AssetService {private final AssetRepository repo; public AssetService(AssetRepository r){repo=r;} public List<Asset> all(String q){return q==null||q.isBlank()?repo.findAll():repo.findAll().stream().filter(a->a.getAssetTag().toLowerCase().contains(q.toLowerCase())||a.getName().toLowerCase().contains(q.toLowerCase())).toList();} public Asset save(Asset a){if(repo.existsByAssetTag(a.getAssetTag()))throw new IllegalArgumentException("Asset tag already exists");if(a.getStatus()==null)a.setStatus(AssetStatus.AVAILABLE);if(a.getStatus()==AssetStatus.RETIRED&&a.getAssignedUser()!=null)throw new IllegalArgumentException("Retired assets cannot be assigned");return repo.save(a);}}
